<?php include 'auth/cek_login.php';include 'koneksi.php';$q=mysqli_query($conn,'SELECT t.*,p.nama pelanggan,m.merk,m.tipe,m.nomor_polisi FROM transaksi t JOIN pelanggan p ON p.id=t.id_pelanggan JOIN mobil m ON m.id=t.id_mobil ORDER BY t.id DESC');?><!doctype html><html><head><title>Laporan</title><link rel="stylesheet" href="assets/style.css"></head><body><main><h1>Laporan Penyewaan Mobil</h1><button onclick="print()">Cetak</button><table><tr><th>Kode</th><th>Pelanggan</th><th>Mobil</th><th>Sewa</th><th>Kembali</th><th>Total</th><th>Status</th></tr><?php while($x=mysqli_fetch_assoc($q)):?><tr><td><?=$x['kode_transaksi']?></td><td><?=$x['pelanggan']?></td><td><?=$x['merk'].' '.$x['tipe'].' '.$x['nomor_polisi']?></td><td><?=$x['tanggal_sewa']?></td><td><?=$x['tanggal_rencana_kembali']?></td><td>Rp <?=number_format($x['total_harga'],0,',','.')?></td><td><?=$x['status']?></td></tr><?php endwhile;?></table></main></body></html>
